def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= 500:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.6
    elif hp <= 4:
        urgency += 0.35
    if no_water >= 2:
        urgency += 0.5
    elif no_water == 1:
        urgency += 0.2

    market = 0.0
    if highest_prev >= 120:
        market = 0.75
    elif highest_prev >= 90:
        market = 0.62
    elif highest_prev >= 60:
        market = 0.5
    elif highest_prev >= 35:
        market = 0.38
    else:
        market = 0.28

    target_ratio = 0.22 + 0.28 * supply_pressure + urgency + market * 0.35
    target_ratio += desperate_count * 0.04
    target_ratio += min(rich_count, 2) * 0.03

    if supply >= 22 and hp >= 5 and no_water == 0:
        target_ratio -= 0.12
    if supply <= 17:
        target_ratio += 0.1

    if target_ratio < 0.12:
        target_ratio = 0.12
    if target_ratio > 0.95:
        target_ratio = 0.95

    base_bid = DAILY_SALARY * target_ratio

    if highest_prev > 0:
        if urgency >= 0.5:
            base_bid = max(base_bid, min(highest_prev + 2.0, DAILY_SALARY * 1.15))
        elif supply <= 17:
            base_bid = max(base_bid, min(avg_prev + 3.0, DAILY_SALARY * 0.95))
        else:
            base_bid = max(base_bid, min(avg_prev * 0.92 + 1.0, DAILY_SALARY * 0.8))

    if hp <= 2 or no_water >= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.88)
    elif hp <= 4 and supply <= 18:
        base_bid = max(base_bid, DAILY_SALARY * 0.72)

    if day >= 8 and hp >= 6 and budget < 180:
        base_bid *= 0.9

    if budget < DAILY_SALARY * 0.6:
        base_bid = min(base_bid, budget)
    else:
        base_bid = min(base_bid, budget, DAILY_SALARY * 1.2)

    if base_bid < 0:
        base_bid = 0.0

    return float(base_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 50.0

    supply = day_context['supply']
    num_players = len(alive_opponents) + 1
    pressure = (num_players * WATER_REQ) / supply

    bid = avg_prev * (1.0 + (pressure - 1.0) * 0.5)
    if my_status['hp'] < 4:
        bid = max(bid, DAILY_SALARY * 0.8)

    return min(my_status['budget'], max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponents' previous traces
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid on yesterday's highest bid
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
    else:
        highest_prev = 0

    # Adjust based on my health
    if my_status['hp'] <= 2:
        # Desperate: bid high to secure water
        bid = max(DAILY_SALARY * 0.9, highest_prev + 2)
    elif my_status['hp'] <= 5:
        # Moderate health: competitive
        bid = max(DAILY_SALARY * 0.6, highest_prev + 1)
    else:
        # Healthy: conserve budget, bid just enough
        bid = max(DAILY_SALARY * 0.4, highest_prev + 0.5)

    # Ensure bid does not exceed budget and is non-negative
    bid = max(0, min(my_status['budget'], bid))
    return float(bid)
